<script setup lang="ts">
import DateField from './DateField.vue';
import {ref,computed,watch as observe,onMounted,onUnmounted} from 'vue';
import {sourceName,title,time,utc,duration,http,health,region,type Row} from '../presentation/zh';
import {safeOfficialUrl} from '../api/client';import {stream} from '../composables/stream';
const props=defineProps<{monitor:Row;catalog:Row;token?:string;healthOnly?:boolean}>();
const sources=ref<Row[]>([]),events=ref<Row[]>([]),error=ref(''),busy=ref(false),connection=ref('正在连接'),qualified=ref(0),received=ref(''),source=ref(''),area=ref(''),category=ref(''),state=ref(''),watch=ref(false),dimension=ref('published_at'),start=ref(''),end=ref(''),page=ref(0),lastQuery=ref(''),more=ref(false);
const total=ref<number>();
const filterOpen=ref(window.innerWidth>650);let abort=new AbortController(),refreshTimer:ReturnType<typeof setTimeout>|undefined;let pendingRefresh=false;const seen=new Set<string>();observe(()=>props.monitor.checked_at,()=>void load());
async function post<T>(path:string,body:unknown={}):Promise<T>{const r=await fetch('/api'+path,{method:'POST',headers:{'Content-Type':'application/json',...(props.token?{Authorization:'Bearer '+props.token}:{})},body:JSON.stringify(body)});if(!r.ok)throw new Error(`请求失败（HTTP ${r.status}）`);return r.json();}
const merged=computed(()=>sources.value.map(s=>({...props.monitor.sources?.find((m:Row)=>m.id===s.id),...s})));
const healthRows=computed(()=>merged.value.filter(s=>(!source.value||s.id===source.value)&&(!area.value||region(s.id)===area.value)&&(!state.value||health(s).key===state.value)));
const matching=computed(()=>events.value);
const latestCheck=computed(()=>merged.value.map(s=>s.last_check||s.last_attempt).filter(Boolean).sort((a,b)=>Date.parse(b)-Date.parse(a))[0]);
const recentSuccess=computed(()=>merged.value.map(s=>s.last_success||s.last_successful_check).filter(Boolean).sort((a,b)=>Date.parse(b)-Date.parse(a))[0]);
const summary=computed(()=>[['已登记来源',merged.value.length],['正常运行',merged.value.filter(s=>health(s).key==='normal').length],['异常来源',merged.value.filter(s=>['failed','unauthorized'].includes(health(s).key)).length],['待配置来源',merged.value.filter(s=>health(s).key==='pending').length],['最近成功同步',time(recentSuccess.value)],['本页符合通知资格的新消息',qualified.value]]);
async function load(reset=false){if(busy.value){pendingRefresh=true;return;}busy.value=true;error.value='';if(reset)page.value=0;try{if(start.value&&end.value&&start.value>end.value)throw new Error('开始日期不能晚于结束日期');const [s,e]=await Promise.all([post<Row[]>('/sources/query'),post<{items:Row[];total:number;queried_at:string}>('/ui/official-query',{source:source.value,region:area.value,category:category.value,state:state.value,start:start.value,end:end.value,dimension:dimension.value,watchOnly:watch.value,page:page.value})]);sources.value=s;events.value=e.items;total.value=e.total;more.value=(page.value+1)*50<e.total;lastQuery.value=e.queried_at;}catch(e){error.value=(e as Error).message;}finally{busy.value=false;if(pendingRefresh){pendingRefresh=false;refreshTimer=setTimeout(()=>void load(),1000);}}}
async function reset(){source.value='';area.value='';category.value='';state.value='';start.value='';end.value='';watch.value=false;dimension.value='published_at';await load(true);}
async function paginate(delta:number){page.value=Math.max(0,page.value+delta);await load();}
onMounted(async()=>{await load();try{const cursor=await post<{cursor:string}>('/stream/cursor');if(abort.signal.aborted)return;void stream(props.token||'',abort.signal,async notices=>{received.value=new Date().toISOString();for(const n of notices)if(!seen.has(String(n.data.event_id))&&n.data.delivery_type==='LIVE'&&n.data.important_alert_eligible===true&&!n.data.replay_flag){qualified.value++;seen.add(String(n.data.event_id));if(seen.size>500)seen.delete(seen.values().next().value!);}const receipts=notices.filter(n=>n.data.delivery_id).map(n=>({deliveryId:n.data.delivery_id,receivedAt:n.data.client_received_at}));if(receipts.length)try{await post('/stream/ack-batch',receipts);}catch{error.value='部分推送确认失败，未计为完整交付';}if(notices.some(n=>!n.data.checkpoint)){clearTimeout(refreshTimer);refreshTimer=setTimeout(()=>void load(),1000);}},s=>connection.value=s,cursor.cursor);}catch{connection.value='实时连接已断开';}});
onUnmounted(()=>{abort.abort();clearTimeout(refreshTimer);});
</script>
<template>
<div class="screen-note"><div>最新来源检查：<time :title="'UTC原值：'+utc(latestCheck)">{{time(latestCheck)}}</time> · 查询时间：<time :title="'UTC原值：'+utc(lastQuery)">{{time(lastQuery)}}</time>（北京时间）</div><div>实时推送（SSE）：<strong>{{ connection }}</strong> · 来源采集：{{ lastQuery?merged.filter(s=>s.enabled).length+' 项已启用':'状态未取得' }}；全局开关接口未提供。运行中任务：{{lastQuery?merged.filter(s=>s.job_status==='RUNNING').length:'未知'}} · 来源同步：{{lastQuery?merged.filter(s=>health(s).key==='failed').length+' 个来源需核查':'状态未取得'}}</div></div>
<div v-if="lastQuery" class="summary"><div v-for="[label,value] in summary" :key="String(label)"><span>{{ label }}</span><strong>{{ value }}</strong></div></div>
<details class="panel filter-panel" :open="filterOpen"><summary>筛选工具栏 · 北京时间</summary><div class="filters">
<label>来源<select aria-label="监控来源" v-model="source"><option value="">全部来源</option><option v-for="s in catalog.sources" :key="s.id" :value="s.id">{{ sourceName(s.id,s.name) }}</option></select></label>
<label>国家或地区<select aria-label="国家或地区" v-model="area"><option value="">全部地区</option><option>美国</option><option>欧元区</option><option>中国</option><option>全球</option></select></label>
<label>事件类型<select aria-label="事件类型" v-model="category"><option value="">全部类型</option><option v-for="c in [...new Set(events.map(e=>e.category))]" :key="c">{{c}}</option></select></label>
<label>来源状态<select aria-label="来源状态" v-model="state"><option value="">全部状态</option><option value="normal">正常运行</option><option value="failed">异常来源</option><option value="pending">待配置</option><option value="unauthorized">未授权</option><option value="disabled">未启用</option></select></label>
<label>开始日期<DateField aria-label="开始日期"  v-model="start"/></label><label>结束日期<DateField aria-label="结束日期"  v-model="end"/></label>
<label>时间维度<select aria-label="时间维度" v-model="dimension"><option value="published_at">官方发布时间</option><option value="first_seen_at">首次发现时间</option><option value="collected_at">实际采集时间</option></select></label><label><input type="checkbox" v-model="watch">仅显示关注项</label><button @click="load(true)" :disabled="busy">查询</button><button @click="reset" :disabled="busy">重置</button></div>
<p class="muted">默认不限定日期。所有查询条件作用于数据库完整官方事件范围，按北京时间日界筛选；每页最多50条，不全量加载历史线索。</p></details>
<p v-if="error" role="alert" class="error">{{error}}</p><p v-if="busy" role="status">正在读取真实数据…</p>
<section><h2>数据源健康列表</h2><p class="muted">HTTP 304 表示内容未修改。连接失败意味着可能遗漏，不能解释为没有新消息。</p><div class="health-grid"><div v-for="s in healthRows" :key="s.id" class="health-card" :data-state="health(s).key"><h3>{{sourceName(s.id,s.name)}}</h3><p><strong>{{sourceName(s.id,s.name).split('（')[0]}}：{{health(s).text}}</strong></p><p>来源状态：{{s.http_status===403||s.http_status===429?'受到限制':health(s).key==='pending'?'待配置':health(s).key==='unauthorized'?'待授权':health(s).key==='disabled'?'暂停':health(s).key==='failed'?'访问失败':health(s).key==='normal'?'正常':health(s).key==='running'&&s.consecutive_failures>0?'正在恢复':'正在检查或待核查'}}</p><p>{{http(s.http_status)}}</p><p>最近成功检查：{{time(s.last_success||s.last_successful_check)}}</p><p>最近新增事件：{{time(s.last_new_event,'尚无真实新增样本')}}</p><details><summary>查看诊断详情</summary><p>最近来源检查：{{time(s.last_check||s.last_attempt)}}</p><p>自动采集：{{s.enabled?'已启用':'未启用'}} · 许可：{{s.license_status==='APPROVED'?'限定用途已核查':'待核查'}}</p><p>{{health(s).key==='failed'?'当前异常原因':'历史最近异常（非本次失败）'}}：{{s.http_status===403?'官方服务器拒绝访问；未绕过限制':s.last_error_detail||s.error_detail||s.error_code||'未提供错误原因'}}</p><p>检查间隔：{{duration(s.interval_seconds)}} · 连续失败：{{s.consecutive_failures??'未提供'}}</p><p>原始状态码：{{s.http_status??'未提供'}}</p><p>最近成功检查 UTC：{{utc(s.last_success||s.last_successful_check)}}</p></details></div></div><p v-if="!healthRows.length&&!busy" class="empty">{{error?'来源运行数据暂不可用':'当前筛选无来源记录'}}</p></section>
<section v-if="!props.healthOnly" class="panel feed event-list"><h2>官方发布事件列表</h2><p class="muted">第 {{page+1}} 页 · 符合条件共 {{total??'未取得'}} 条 · 当前页 {{matching.length}} 条 · 原始事实核验与翻译状态分别展示</p><p v-if="!matching.length&&!busy" class="empty">暂无真实数据</p>
<article v-for="e in matching" :key="e.id" :data-event-id="e.id"><div class="event-meta"><span>{{sourceName(e.source_id,e.publisher)}}</span><span>官方一级来源（{{e.level}}）</span><span>{{e.category}}</span><span>{{e.facts?.some((f:Row)=>f.status==='INDEPENDENT_SUPPORTED')?'有独立支持证据':'来源已核查，实质事实待核实'}}</span></div><h3>{{title(e).text}}</h3><p class="muted">{{title(e).status}} · {{e.ingestion_kind==='HISTORICAL_BACKFILL'?'历史回填，不作为新消息提醒':'监控记录，通知资格另行核验'}}</p><div class="event-meta"><span>官方发布时间：{{time(e.published_at,'官方发布时间未知')}}</span><span>首次发现时间：<time :title="'UTC原值：'+utc(e.first_seen_at)">{{time(e.first_seen_at)}}</time></span></div>
<details><summary>原文与技术证据</summary><p class="original">官方原文标题：{{e.original_title}}</p><dl><dt>原始链接</dt><dd>{{e.source_url}}</dd><dt>原始时间及 UTC</dt><dd>{{e.published_at||'官方发布时间未知'}}<br>{{utc(e.published_at)}}</dd><dt>原站时区</dt><dd>接口未提供；不根据机构所在地猜测</dd><dt>实际采集时间</dt><dd><time :title="'UTC原值：'+utc(e.collected_at)">{{time(e.collected_at)}}</time> · {{utc(e.collected_at)}}</dd><dt>数据库入库时间</dt><dd>{{time(e.ingested_at)}} · {{utc(e.ingested_at)}}</dd><dt>SSE 推送时间</dt><dd>{{time(e.first_server_sent_at,'尚无正式首次发送记录')}} · {{utc(e.first_server_sent_at)}}</dd><dt>客户端最近接收</dt><dd>{{time(received,'本页尚未收到推送')}}（页面级）</dd><dt>响应状态及采集任务</dt><dd>{{http(e.http_status)}} · 采集任务 {{e.collection_job_id||'未提供'}}</dd><dt>证据ID</dt><dd>{{e.evidence_id}}</dd><dt>SHA-256 内容哈希</dt><dd>{{e.raw_content_hash}}</dd><dt>证据版本数</dt><dd>{{e.evidence_versions}}</dd><dt>{{e.ingestion_kind==='HISTORICAL_BACKFILL'?'历史发现延迟':'首次发现距发布'}}</dt><dd>{{e.published_at?duration((Date.parse(e.first_seen_at)-Date.parse(e.published_at))/1000):'官方发布时间未知，无法计算'}}，不等同实时传播延迟</dd></dl></details><a v-if="safeOfficialUrl(e.source_url)" :href="e.source_url" target="_blank" rel="noopener">查看原始来源</a><a :href="'#/research?event='+e.id">打开金融事件研究详情</a>
</article><footer><button @click="paginate(-1)" :disabled="busy||page===0">上一页</button><span>第 {{page+1}} 页</span><button @click="paginate(1)" :disabled="busy||!more">下一页</button></footer></section>
<details v-if="!props.healthOnly" class="panel feed"><summary>全球官方发布日历 · 计划日期不代表已发布</summary><div class="calendar-list"><article v-for="c in props.monitor.calendar" :key="c.id"><h3>{{sourceName(c.source_id)}} · 官方发布计划</h3><p class="original">{{c.official_title}}</p><p>计划日期：{{c.planned_date}} · 原站计划时刻：{{c.planned_time_text||'未知'}}</p><p class="muted">原站时区：{{c.source_timezone}}（所在地信息，未猜测换算） · 采集：<time :title="'UTC原值：'+utc(c.collected_at)">{{time(c.collected_at)}}</time> · 本地版本 {{c.version}}</p><a v-if="safeOfficialUrl(c.source_url)" :href="c.source_url" target="_blank" rel="noopener">查看官方日历</a></article></div></details>
</template>
